"use strict";
let kept = null;
exports.params = () => ({ model: "m" });
exports.create = (p) => JSON.stringify(p);
exports.keep = (v) => {
  kept = v;
};
exports.same = (v) => v === kept;
exports.ident = (v) => {
  kept = v;
  return v;
};
exports.mutateKept = () => {
  kept.n = 99;
};
exports.mutateKeptName = () => {
  kept.name = "mutated";
};
exports.send = (input) => JSON.stringify(input);
